using System.Windows;
using System.Windows.Controls;
namespace CremaTools;

public partial class MainWindow
{
    TextBlock? updateMessage; bool updating;
    void ShowUpdates() { Reset("updates", "Toujours à jour", "Les mises à jour viennent de l’espace dédié CrémaTools. Leur signature et leur téléchargement sont vérifiés avant installation."); Page.Children.Add(Text("Version installée : " + UpdateEngine.Version, 18, true)); var automatic = new CheckBox { Content = "Chercher et préparer automatiquement les mises à jour", IsChecked = UpdateEngine.Settings.AutoUpdate }; automatic.Checked += (_, _) => { UpdateEngine.Settings.AutoUpdate = true; UpdateEngine.Save(); }; automatic.Unchecked += (_, _) => { UpdateEngine.Settings.AutoUpdate = false; UpdateEngine.Save(); }; Page.Children.Add(automatic); Page.Children.Add(Text("Quand une nouvelle version est prête, elle est installée silencieusement à la fermeture de CrémaTools. Vos documents et coffres restent conservés. Windows peut demander une confirmation selon les paramètres du poste.", 13, false, "#607087")); Page.Children.Add(Text("Adresse du service de mise à jour", 14, true)); var address = new TextBox { Text = UpdateEngine.Settings.UpdateUrl }; Page.Children.Add(address); Page.Children.Add(Button("Enregistrer cette adresse", () => { if (!Uri.TryCreate(address.Text.Trim(), UriKind.Absolute, out var uri) || uri.Scheme != "https") throw new Exception("Indiquez une adresse HTTPS."); UpdateEngine.Settings.UpdateUrl = address.Text.Trim(); UpdateEngine.Save(); Status.Text = "Adresse enregistrée. Les manifestes doivent toujours porter la signature CrémaTools."; })); updateMessage = Text(UpdateEngine.Ready ? "Version " + UpdateEngine.Settings.PendingVersion + " prête à installer à la fermeture." : "Cliquez sur Vérifier pour rechercher une nouvelle version.", 14); Page.Children.Add(updateMessage); Page.Children.Add(Row(AsyncButton("Vérifier maintenant", () => CheckUpdates(false), true), Button("Installer et fermer", () => { if (!UpdateEngine.Ready) throw new Exception("Aucune nouvelle version n’est prête."); if (busy) throw new Exception("Attendez la fin du traitement en cours."); Close(); }))); Page.Children.Add(Text("Seules les informations de mise à jour sont téléchargées. Vos documents et le coffre ne sont jamais envoyés à ce service.", 12, false, "#607087")); }
    async Task CheckUpdates(bool silent) { if (updating) return; updating = true; using var cancel = new CancellationTokenSource(TimeSpan.FromMinutes(10)); try { if (!silent) { Status.Text = "Recherche d’une mise à jour…"; if (updateMessage is not null) updateMessage.Text = Status.Text; } var next = await UpdateEngine.Check(cancel.Token); if (next is null) { if (!silent) { Status.Text = "Vous avez la dernière version disponible."; if (updateMessage is not null) updateMessage.Text = Status.Text; } return; } await UpdateEngine.Download(next, new Progress<string>(s => { Status.Text = s; if (active == "updates" && updateMessage is not null) updateMessage.Text = s; }), cancel.Token); Status.Text = "Version " + next.Version + " prête. Installation automatique à la fermeture."; if (active == "updates" && updateMessage is not null) updateMessage.Text = Status.Text; } catch (Exception e) { if (!silent) { Status.Text = "Mise à jour indisponible : " + e.Message; if (updateMessage is not null) updateMessage.Text = Status.Text; } } finally { updating = false; } }
}
